{
  "sql": "SELECT m.chembl_id AS compound_chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, t.chembl_id AS target_chembl_id, t.pref_name AS target_name, t.organism AS target_organism FROM molecule_dictionary m JOIN compound_records cr ON m.molregno = cr.molregno JOIN docs d ON cr.doc_id = d.doc_id JOIN activities act ON cr.record_id = act.record_id JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary t ON a.tid = t.tid LEFT JOIN compound_structures cs ON m.molregno = cs.molregno WHERE act.standard_type = 'IC50' AND act.standard_units = 'nM' AND t.pref_name = 'Isocitrate dehydrogenase [NADP] cytoplasmic' AND t.organism = 'Homo sapiens' ORDER BY m.chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi), a.description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, t.chembl_id, t.pref_name, t.organism"
